SELECT tblProviders.ProviderID, tblProviders.ProviderName, tblClientServicePlan.FiscalYear, tblClientServicePlan.HoursPerWeek AS WeeklyHours, tblClientServicePlan.WeeklyCost, tblClientServicePlan.AnnualEstCost, tblProviderServiceCatalog.RatePerHour, tblServices.ServiceID, tblServices.ServiceName, tblClients.ClientID, Trim(Nz([LastName],"") & ", " & Nz([FirstName],"")) AS ClientName
FROM tblServices INNER JOIN (tblProviders INNER JOIN ((tblClients INNER JOIN tblClientServiceNeeds ON tblClients.ClientID = tblClientServiceNeeds.ClientID) INNER JOIN (tblProviderServiceCatalog INNER JOIN tblClientServicePlan ON tblProviderServiceCatalog.ProviderServiceCatalogID = tblClientServicePlan.ProviderServiceCatalogID) ON tblClientServiceNeeds.ClientServiceNeedID = tblClientServicePlan.ClientServiceNeedID) ON tblProviders.ProviderID = tblProviderServiceCatalog.ProviderID) ON (tblServices.ServiceID = tblClientServiceNeeds.ServiceID) AND (tblServices.ServiceID = tblProviderServiceCatalog.ServiceID)
WHERE (((tblClientServicePlan.Status)<>"Cancelled"));
